/* From Uiverse.io by PriyanshuGupta28 - Tags: button, 3d button, cool button, button hover effect , smooth effect , smooth button */
.__UIV_SCOPE__ .button {
  display: inline-block;
  padding: 15px 30px;
  background: linear-gradient(45deg, #00b5ff, #005eff);
  color: #fff;
  font-size: 18px;
  font-weight: bold;
  text-transform: uppercase;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: box-shadow 0.3s, transform 0.3s;
}

.__UIV_SCOPE__ .button::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(255, 255, 255, 0.1);
  transform: translateY(100%) rotateX(90deg);
  transition: transform 0.3s ease-in-out;
}

.__UIV_SCOPE__ .button:hover::before {
  transform: translateY(0) rotateX(0);
}

.__UIV_SCOPE__ .button::after {
  content: "";
  position: absolute;
  top: -5px;
  left: -5px;
  width: calc(100% + 10px);
  height: calc(100% + 10px);
  border-radius: 15px;
  border: 1px solid #00b5ff;
  z-index: -1;
}

    /* Hover Effect */
.__UIV_SCOPE__ .button:hover {
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  transform: scale(1.05);
}

    /* Active Effect */
.__UIV_SCOPE__ .button:active {
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
  transform: scale(0.95);
}
